function formatEvent({ id, event, data }) {
  let text = "";
  if (id !== undefined) text += `id: ${id}\n`;
  if (event !== undefined) text += `event: ${event}\n`;
  for (const line of data.split("\n")) text += `data: ${line}\n`;
  return text + "\n";
}

console.log(JSON.stringify(formatEvent({ id: 4, event: "status", data: '{"status":"delivered"}' })));
