function splitEvents(buffer) {
  const blocks = [];
  let end;
  while ((end = buffer.indexOf("\n\n")) !== -1) {
    blocks.push(buffer.slice(0, end));
    buffer = buffer.slice(end + 2);
  }
  return { blocks, rest: buffer };
}

let rest = "";
