function createClient(port) {
  let nextId = 1;
  const pending = new Map();
  port.onmessage = ({ data }) => {
    const call = pending.get(data.id);
    if (!call) return;
    pending.delete(data.id);
    if ("error" in data) call.reject(new Error(data.error));
    else call.resolve(data.result);
  };
  return {
    call(method, args) {
      return new Promise((resolve, reject) => {
        const id = nextId++;
        pending.set(id, { resolve, reject });
        port.postMessage({ id, method, args });
      });
    },
  };
}

const fakeWorker = {
  onmessage: null,
  postMessage({ id, method, args }) {
    setTimeout(() => {
      if (method === "total") this.onmessage({ data: { id, result: args.reduce((a, b) => a + b, 0) } });
      else this.onmessage({ data: { id, error: `unknown method ${method}` } });
    }, method === "total" ? 20 : 5);
  },
};

const client = createClient(fakeWorker);
const total = client.call("total", [850000, 230000]);
const refund = client.call("refund", {}).catch((error) => error.message);
console.log(await total);
