function createRooms() {
  const rooms = new Map();
  return {
    join(room, member) {
      if (!rooms.has(room)) rooms.set(room, new Set());
      rooms.get(room).add(member);
    },
    leave(room, member) {
      const members = rooms.get(room);
      if (!members) return;
      members.delete(member);
      if (members.size === 0) rooms.delete(room);
    },
    broadcast(room, sender, text) {
      return [...(rooms.get(room) ?? [])].filter((m) => m !== sender).map((m) => `${m}: ${text}`);
    },
    count: () => rooms.size,
  };
}

const rooms = createRooms();
rooms.join("ORD-1042", "customer");
rooms.join("ORD-1042", "courier");
rooms.join("ORD-2001", "customer-2");
